def is_good(m, memo):
    if m in memo:
        return memo[m]

    s = str(m)
    if len(s) == 1:
        memo[m] = True
        return True

    # Check if digits are distinct and nonzero
    digits = [int(d) for d in s]
    if len(set(digits)) != len(digits) or 0 in digits:
        memo[m] = False
        return False

    # Check if removing one digit results in a divisor that is good
    for i in range(len(s)):
        m_prime_s = s[:i] + s[i+1:]
        if not m_prime_s: # Should not happen for m > 9
            continue
        m_prime = int(m_prime_s)
        if m % m_prime == 0:
            if is_good(m_prime, memo):
                memo[m] = True
                return True

    memo[m] = False
    return False

