def get_good_numbers(max_digits):
    good_numbers_by_digit_count = [set() for _ in range(max_digits + 1)]

    # G1
    for i in range(1, 10):
        good_numbers_by_digit_count[1].add(i)

    for k in range(2, max_digits + 1):
        for m_prime in good_numbers_by_digit_count[k-1]:
            # m_prime is a good number with k-1 digits.
            # We want to find m with k distinct nonzero digits such that m_prime is m with one digit removed.
            # The digit removed can be at any position (0 to k-1 in m_prime's string representation).
            s_prime = str(m_prime)
            for i in range(len(s_prime) + 1):
                # Try inserting a digit d in position i
                for d in range(1, 10):
                    s_m = s_prime[:i] + str(d) + s_prime[i:]
                    m = int(s_m)

                    # Check if m has k distinct nonzero digits
                    # Note: Since m_prime already has k-1 distinct nonzero digits, 
                    # we only need to check if d is not in m_prime and d is not zero.
                    # (d is already in range(1, 10), so d is not 0).
                    s_m_digits = [int(digit) for digit in s_m]
                    if len(set(s_m_digits)) == len(s_m_digits):
                        if m % m_prime == 0:
                            good_numbers_by_digit_count[k].add(m)

    return good_numbers_by_digit_count

