def is_good_brute(m, memo):
    if m in memo:
        return memo[m]

    s = str(m)
    if len(s) == 1:
        memo[m] = True
        return True

    for i in range(len(s)):
        m_prime_s = s[:i] + s[i+1:]
        m_prime = int(m_prime_s)
        if m % m_prime == 0:
            if is_good_brute(m_prime, memo):
                memo[m] = True
                return True

    memo[m] = False
    return False

def solve():
    memo = {}
    for i in range(1, 10):
        memo[i] = True

    max_good = 0
    for k in range(1, 10):
        for digits in itertools.permutations(range(1, 10), k):
            m = 0
            for d in digits:
                m = m * 10 + d
            if is_good_brute(m, memo):
                if m > max_good:
                    max_good = m
    return max_good

